#include <gtest/gtest.h>

#include <string>

#include "XtcMetadata.h"

namespace {

std::string shelfFixture(const char* name) { return std::string(SHELF_FIXTURES) + "/" + name; }

}  // namespace

// XTC keeps title/author inside its header (0x38 / 0xB8); the fixture is
// generated by test/fixtures/shelf/generate_shelf_fixtures.py.
TEST(ShelfXtc, ReadsHeaderMetadata) {
  shelf::BookMeta meta;
  ASSERT_TRUE(shelf::readXtcMetadata(shelfFixture("book.xtc"), meta));
  EXPECT_EQ("Тестовая книга", meta.title);
  EXPECT_EQ("Александр Тестов", meta.author);
}

TEST(ShelfXtc, RejectsTruncatedHeader) {
  shelf::BookMeta meta;
  EXPECT_FALSE(shelf::readXtcMetadata(shelfFixture("broken.xtc"), meta));
  EXPECT_TRUE(meta.title.empty());
}

TEST(ShelfXtc, RejectsMissingFile) {
  shelf::BookMeta meta;
  EXPECT_FALSE(shelf::readXtcMetadata("/nonexistent/shelf/missing.xtc", meta));
}
